// a slot's rarity has nothing left to offer: the next lower one, then the higher ones
const FALLBACK = { ULTRA: ['ULTRA', 'ROGUE', 'MASTER'], ROGUE: ['ROGUE', 'ULTRA', 'MASTER'], MASTER: ['MASTER', 'ROGUE', 'ULTRA'] };
const PROOF_FLOORS = [125, 175];
const pickOne = (list, r) => list[Math.min(list.length - 1, Math.floor(r * list.length))];

