  id: 'coop-items', title: '联机道具', hint: '两人轮流各挑1个 · 左下角可付费刷新', count: 4, reroll: true, exclusive: true,
  emptyText: '联机道具：现在没有还能再拿的联机道具了。',
  when: ctx => FLOORS.includes(ctx.wave),
  // the six floors are all odd, where 2P always picks first in the normal reward: here the two take turns, 1P first on 5
  first: ctx => (FLOORS.indexOf(ctx.wave) % 2 === 0 ? 'p1' : 'p2'),
